import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Img, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ImageComparisonSliderProps = Record<string, any>;

const ImageComparisonSlider: React.FC<ImageComparisonSliderProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 5,
  beforeImage = "https://malloy.blob.core.windows.net/web/testing/1.jpg",
  afterImage = "https://malloy.blob.core.windows.net/web/testing/2.jpg",
  orientation = "Horizontal",
  revealDirection = "StartToEnd",
  dividerColor = "#FFFFFF",
  dividerWidth = 4,
  showHandle = true,
  handleColor = "#FFFFFF",
  handleSize = 50,
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const durationInFrames = durationInSeconds * fps;

  // Determine Start/End percentages based on direction
  const startPos = revealDirection === "StartToEnd" ? 0 : 100;
  const endPos = revealDirection === "StartToEnd" ? 100 : 0;

  // Animate the slider position (0 to 100)
  const sliderPosition = interpolate(
    frame,
    [0, durationInFrames],
    [startPos, endPos],
    {
      easing: Easing.inOut(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const isHorizontal = orientation === "Horizontal";

  // Calculate dynamic styles based on slider position
  // We use `inset` for clip-path. 
  // Inset format: top right bottom left
  // Revised Layering Strategy:
  // Layer 1 (Bottom): After Image (Full width/height)
  // Layer 2 (Top): Before Image (Clipped)
  
  // Clip Path Logic for Layer 2 (Before Image):
  // If Horizontal: We want to show the LEFT side up to sliderPosition %.
  //   - Clip right side: inset(0 (100-sliderPosition)% 0 0)
  // If Vertical: We want to show the TOP side up to sliderPosition %.
  //   - Clip bottom side: inset(0 0 (100-sliderPosition)% 0)

  const clipValue = 100 - sliderPosition;
  const clipPathStyle = isHorizontal
    ? `inset(0 ${clipValue}% 0 0)`
    : `inset(0 0 ${clipValue}% 0)`;

  // Divider Position
  const dividerLeft = isHorizontal ? `${sliderPosition}%` : "0";
  const dividerTop = isHorizontal ? "0" : `${sliderPosition}%`;
  const dividerW = isHorizontal ? dividerWidth : width;
  const dividerH = isHorizontal ? height : dividerWidth;
  
  // Center the divider line itself so the position represents the center
  const dividerTransform = isHorizontal
    ? `translateX(-${dividerWidth / 2}px)`
    : `translateY(-${dividerWidth / 2}px)`;

  // Handle Position
  const handleLeft = isHorizontal 
    ? `calc(${sliderPosition}% - ${handleSize / 2}px)`
    : `calc(50% - ${handleSize / 2}px)`;
  
  const handleTop = isHorizontal
    ? `calc(50% - ${handleSize / 2}px)`
    : `calc(${sliderPosition}% - ${handleSize / 2}px)`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter" }}>
      
      {/* 1. Base Layer: After Image (Normally on the right/bottom) */}
      <AbsoluteFill>
        <Img
          src={afterImage}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
          }}
        />
      </AbsoluteFill>

      {/* 2. Top Layer: Before Image (Clipped) */}
      <AbsoluteFill style={{ clipPath: clipPathStyle }}>
        <Img
          src={beforeImage}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
          }}
        />
      </AbsoluteFill>

      {/* 3. Divider Line */}
      <div
        style={{
          position: "absolute",
          left: dividerLeft,
          top: dividerTop,
          width: dividerW,
          height: dividerH,
          backgroundColor: dividerColor,
          transform: dividerTransform,
          boxShadow: "0 0 10px rgba(0,0,0,0.5)",
          zIndex: 20,
        }}
      />

      {/* 4. Handle */}
      {showHandle && (
        <div
          style={{
            position: "absolute",
            left: handleLeft,
            top: handleTop,
            width: handleSize,
            height: handleSize,
            borderRadius: "50%",
            backgroundColor: handleColor,
            border: `4px solid ${dividerColor}`, // Outline to match divider
            boxShadow: "0 4px 10px rgba(0,0,0,0.4)",
            zIndex: 30,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {/* Double Arrow (Left/Right) */}
           <div style={{
                position: 'absolute',
                width: '100%', 
                height: '100%', 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'center'
           }}>
             <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#333" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ transform: isHorizontal ? 'none' : 'rotate(90deg)'}}>
                <path d="M19 12H5" />
                <path d="M12 19l-7-7 7-7" />
                <path d="M12 5l7 7-7 7" />
             </svg>
           </div>
        </div>
      )}

    </AbsoluteFill>
  );
};

export default ImageComparisonSlider;